def set_purchase_methods(apps, schema_editor):
    """
    Keep what buyers see today: under-construction properties (the page
    already offered installments for all of them) and any property with
    installments enabled become "cash or installments"; the rest "cash".
    Existing buyer plans get their start date.
    """
    Property = apps.get_model('properties', 'Property')
    ConstructionInstallment = apps.get_model('properties', 'ConstructionInstallment')
    for prop in Property.objects.all():
        both = prop.supports_installments or prop.property_category == 'under_construction'
        prop.purchase_methods = 'both' if both else 'cash'
        prop.supports_installments = both
        prop.save(update_fields=['purchase_methods', 'supports_installments'])
    for plan in ConstructionInstallment.objects.filter(start_date__isnull=True):
        plan.start_date = plan.created_at.date()
        plan.save(update_fields=['start_date'])


